def _preview_cost(self) -> int:
    return 1

def _step_cost(self, delta_time: float) -> int:
    return max(0, int(round(delta_time * 10)))

def _solver_cfg(self, solver: str) -> dict[str, float | str] | None:
    if solver != "sde":
        return None
    return {"noise_scale": 0.01, "sigma_max": 1.25, "min_time": 0.02}

def _latent_rmse(self, a: Any, b: Any) -> float:
    return float((a.float() - b.float()).pow(2).mean().sqrt().detach().cpu().item())

